const REPORT_LOGO_DIMENSIONS = { width: 1559, height: 371 } as const;

let cachedLogoBuffer: Buffer | undefined;

export function getReportLogoBuffer(): Buffer | undefined {
  if (cachedLogoBuffer) {
    return cachedLogoBuffer;
  }

  try {
    cachedLogoBuffer = Buffer.from(REPORT_LOGO_PNG_BASE64, 'base64');
    return cachedLogoBuffer;
  } catch {
    return undefined;
  }
}

export function getReportLogoDimensions(): { width: number; height: number } {
  return REPORT_LOGO_DIMENSIONS;
}

export const REPORT_LOGO_FALLBACK_TEXT = 'XYTE';
